import React, { useState, useEffect } from "react";
import api from "../../api";
import { FaPlus } from "react-icons/fa";
import Create from "../form/penghargaan/create";
import Update from "../form/penghargaan/update";
import Delete from "../form/penghargaan/delete";

const Penghargaan = () => {
  const [data, setData] = useState([]);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showUpdateModal, setShowUpdateModal] = useState(false);
  const [dataToDelete, setDataToDelete] = useState(null);
  const [currentData, setCurrentData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/penghargaan")
      .then((response) => {
        setData(response.data.penghargaan);
      })
      .catch((error) => {
        console.error("Error fetching data:", error);
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  const handleOpenCreateModal = () => {
    setShowCreateModal(true);
  };

  const handleOpenUpdateModal = (row) => {
    setCurrentData(row);
    setShowUpdateModal(true);
  };

  const handleCloseModal = () => {
    setShowCreateModal(false);
    setShowUpdateModal(false);
    setCurrentData(null);
  };

  const handleOpenDeleteModal = (scheduleId) => {
    setDataToDelete(scheduleId);
  };

  const handleSubmitCreate = (formData) => {
    setLoading(true);

    const formDataToSend = new FormData();
    formDataToSend.append("judul", formData.judul);
    formDataToSend.append("kategori", formData.kategori);
    formDataToSend.append("content", formData.content);
    if (formData.gambar) formDataToSend.append("gambar", formData.gambar);

    api.post("/penghargaan/create", formDataToSend)
      .then((response) => {
        setData([...data, response.data]);
        setShowCreateModal(false);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error submitting form:", error);
        setLoading(false);
      });
  };

  const handleSubmitUpdate = (formData) => {
    setLoading(true);

    const formDataToSend = new FormData();
    formDataToSend.append("judul", formData.judul);
    formDataToSend.append("kategori", formData.kategori);
    formDataToSend.append("content", formData.content);
    if (formData.gambar) formDataToSend.append("gambar", formData.gambar);

    api.post(`/penghargaan/update/${currentData.id}`, formDataToSend)
      .then((response) => {
        const updatedData = data.map((item) =>
          item.id === currentData.id ? response.data : item
        );
        setData(updatedData);
        setShowUpdateModal(false);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error updating form:", error);
        setLoading(false);
      });
  };

  const handleDelete = async () => {
    if (dataToDelete) {
      try {
        await api.delete(`/penghargaan/delete/${dataToDelete}`);
        setData(data.filter((item) => item.id !== dataToDelete));
        setDataToDelete(null);
      } catch (error) {
        console.error("Error deleting item:", error);
      }
    }
  };

  return (
    <div>
      <div className="overflow-x-auto bg-white w-full max-w-full mx-auto rounded-lg shadow-lg p-6">
        {/* Button Create Penghargaan */}
        <div className="flex justify-between mb-4">
          <h1 className="text-2xl font-bold mb-4">Data Berita</h1>
          <button
            onClick={handleOpenCreateModal}
            className="bg-teal-500 text-white py-2 px-4 rounded-lg flex items-center"
          >
            <FaPlus className="inline-block mr-2 mb-1" /> Create Artikel
          </button>
        </div>

        {/* Tampilkan tabel penghargaan */}
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Judul</th>
              <th className="px-6 py-3 text-left font-medium">Kategori</th>
              <th className="px-6 py-3 text-left font-medium">Content</th>
              <th className="px-6 py-3 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody>
          {loading ? (
            <tr>
              <td
                colSpan="8"
                className="text-center px-6 py-4 text-gray-500"
              >
                Loading...
              </td>
            </tr>
          ):data.length > 0 ? (
            data.map((row, index) => (
              <tr key={row.id}>
                <td className="px-6 py-4">{index + 1}</td>
                <td className="px-6 py-4">{row.judul}</td>
                <td className="px-6 py-4">{row.kategori}</td>
                <td className="px-6 py-4">{row.content}</td>
                <td className="px-6 py-4">
                  <button
                    onClick={() => handleOpenUpdateModal(row)}
                    className="bg-teal-500 text-white py-1 px-3 rounded-lg mr-2"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleOpenDeleteModal(row.id)}
                    className="bg-red-500 text-white py-1 px-3 rounded-lg"
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))) : (
              <tr>
                <td colSpan="5" className="text-center px-6 py-4 text-gray-500">
                  Tidak ada penghargaan tersedia.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Modal Form */}
      {showCreateModal && (
        <Create
          onSubmit={handleSubmitCreate}
          onClose={handleCloseModal}
          loading={loading}
        />
      )}

      {showUpdateModal && (
        <Update
          onSubmit={handleSubmitUpdate}
          onClose={handleCloseModal}
          initialData={currentData}
          loading={loading}
        />
      )}
      <Delete
        isOpen={dataToDelete !== null}
        onClose={handleCloseModal}
        onDelete={handleDelete}
        loading={loading}
      />
    </div>
  );
};

export default Penghargaan;
